'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useApi } from '@/lib/api/api-provider'
import type { Page } from '@/lib/api/types'
import type { Tag, TagInput } from './types'

const PATH = '/api/shop/tags'
const KEY = ['shop', 'tag'] as const

export interface TagFilters {
  q?: string
  page?: number
  size?: number
  sort?: string
}

const item = (id: number) => `${PATH}/${encodeURIComponent(String(id))}`

export function useTagList(filters: TagFilters) {
  const api = useApi()
  return useQuery({
    queryKey: [...KEY, filters],
    queryFn: () => api.get<Page<Tag>>(PATH, { ...filters }),
    placeholderData: previous => previous,
  })
}

export function useSaveTag() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, input }: { id?: number; input: TagInput }) =>
      id != null ? api.put<Tag>(item(id), input) : api.post<Tag>(PATH, input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}

export function useDeleteTag() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: number) => api.delete(item(id)),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}
